function relay_accepted_enquiry(string $raw, array $capture, bool $intake_only = false, ?callable $scoped_link = null, ?array $recovery_lock = null): \WP_REST_Response {
    $row = $capture['row'] ?? [];
    $english_recovery = in_array($row['notice_version'] ?? null, OFFPLAN_COUNTRY_RECOVERY_NOTICES, true);
    if ($english_recovery !== ($recovery_lock !== null)) return reply(409, 'REQUEST_ID_CONFLICT');
    $mark_pending = static function () use ($capture, $recovery_lock, $row): void {
        if ($recovery_lock === null) { consent_mark_uncertain($capture); return; }
        try { $capture['repository']->markRecoveryPending($row['request_id'], $row['fingerprint'], $recovery_lock); }
        catch (\Throwable $ignored) { /* Do not mask the same-ID retry response. */ }
    };

public function findCapture(string $request): ?array {
    return $this->row($this->db->prepare("SELECT request_id,fingerprint,subject_key,original_revision,decision_version,
        notice_version,analytics,ad_measurement,personalization,eligible,known,state,click_capture_state,
        lead_id,event_id,delivery_pending
        FROM {$this->captures} WHERE request_id=%s", $request));
}
public function withRecoveryLock(string $request, callable $work) {
    $database = $this->row('SELECT DATABASE() AS db_name')['db_name'] ?? null;
    if (!is_string($database) || $database === '') throw new \RuntimeException('Recovery storage unavailable.');
    $name = hash('sha256', 'bsre-enquiry-recovery-v1|' . $database . '|' . $this->captures . '|' . $request);
    $result = $this->row($this->db->prepare(
        'SELECT IF(DATABASE()=%s, GET_LOCK(%s,0), NULL) AS acquired, CONNECTION_ID() AS db_owner', $database, $name
    ));
    if (!in_array($result['acquired'] ?? null, [1, '1'], true) || (int) ($result['db_owner'] ?? 0) < 1) {
        throw new \RuntimeException('Recovery unavailable or busy.');
    }
    $lock = ['database' => $database, 'name' => $name, 'connection' => (int) $result['db_owner']];
    try { return $work($lock); }
    finally {
        try {
            $this->row($this->db->prepare(
                'SELECT IF(DATABASE()=%s AND CONNECTION_ID()=%d, RELEASE_LOCK(%s), NULL) AS released',
                $database, $lock['connection'], $name
            ));
        } catch (\Throwable $ignored) { /* A lost session cannot release a peer's lock. */ }
    }
}

public function requireRecoveryLock(array $lock): void {
    $row = $this->row($this->db->prepare(
        'SELECT (DATABASE()=%s AND CONNECTION_ID()=%d AND IS_USED_LOCK(%s)=CONNECTION_ID()) AS owns_recovery',
        $lock['database'], $lock['connection'], $lock['name']
    ));
    if (!in_array($row['owns_recovery'] ?? null, [1, '1'], true)) throw new \RuntimeException('Recovery lock lost.');
}

public function markRecoveryPending(string $request, string $fingerprint, array $lock): void {
    $this->query($this->db->prepare("UPDATE {$this->captures} SET delivery_pending=1
        WHERE request_id=%s AND fingerprint=%s AND state='STAGED'
        AND DATABASE()=%s AND CONNECTION_ID()=%d AND IS_USED_LOCK(%s)=CONNECTION_ID()",
        $request, $fingerprint, $lock['database'], $lock['connection'], $lock['name']));
}

public function linkRecovery(string $request, string $fingerprint, string $lead, string $event, array $lock): void {
    $changed = $this->query($this->db->prepare("UPDATE {$this->captures}
        SET state='ACCEPTED', lead_id=%s, event_id=%s, delivery_pending=0 WHERE request_id=%s AND fingerprint=%s
        AND ((state='STAGED' AND lead_id='' AND event_id='')
            OR (state='ACCEPTED' AND lead_id=%s AND event_id=%s AND delivery_pending=1))
        AND DATABASE()=%s AND CONNECTION_ID()=%d AND IS_USED_LOCK(%s)=CONNECTION_ID()",
        $lead, $event, $request, $fingerprint, $lead, $event, $lock['database'], $lock['connection'], $lock['name']));
    if ($changed !== 1) throw new \RuntimeException('Recovery receipt could not be linked under its lock.');
}

function offplan_country_recovery_capture(WpConsentRepository $store, string $request, string $fingerprint, string $decision, string $notice): ?array {
    $row = $store->findCapture($request);
    if (!$row || $row['notice_version'] !== $notice
        || !hash_equals($row['fingerprint'], $fingerprint) || !hash_equals($row['decision_version'], $decision)
        || !in_array($row['state'], ['STAGED', 'ACCEPTED'], true)
        || (int) $row['known'] !== 1 || (int) $row['ad_measurement'] !== 1 || (int) $row['eligible'] !== 1
        || (int) $row['analytics'] !== 0 || (int) $row['personalization'] !== 0
        || (int) $row['original_revision'] < 1 || !preg_match('/^[a-f0-9]{64}$/D', $row['subject_key'])
        || $row['click_capture_state'] !== 'NOT_PERMITTED') return null;
    return $row;
}

function offplan_country_recovery_receipt(array $row): \WP_REST_Response {
    if (!consent_valid_receipt_id($row['lead_id'], 'BSRE-')
        || !consent_valid_receipt_id($row['event_id'], 'evt_')) throw new \RuntimeException('Invalid recovery receipt.');
    return response(200, ['accepted' => true, 'lead_id' => $row['lead_id'], 'event_id' => $row['event_id'],
        'measurement' => consent_denied_snapshot(), 'measurement_eligible' => false]);
}

function offplan_country_recover(string $raw, string $request_id, string $decision, string $notice): \WP_REST_Response {
    try {
        $store = consent_repository();
        $request = strtolower($request_id);
        $fingerprint = hash('sha256', $raw);
        $read = static fn () => offplan_country_recovery_capture($store, $request, $fingerprint, $decision, $notice);
        $row = $read();
        if (!$row) return reply(409, 'REQUEST_ID_CONFLICT');
        if ($row['state'] === 'ACCEPTED' && (int) $row['delivery_pending'] === 0) return offplan_country_recovery_receipt($row);

        return $store->withRecoveryLock($request, static function (array $lock) use ($read, $store, $raw): \WP_REST_Response {
            $row = $read();
            $store->requireRecoveryLock($lock);
            if (!$row) return reply(409, 'REQUEST_ID_CONFLICT');
            if ($row['state'] === 'ACCEPTED') {
                $reply = offplan_country_recovery_receipt($row);
                if ((int) $row['delivery_pending'] !== 0) {
                    $store->linkRecovery($row['request_id'], $row['fingerprint'], $row['lead_id'], $row['event_id'], $lock);
                }
                return $reply;
            }
            $capture = ['recorded' => true, 'row' => $row, 'repository' => $store];
            return relay_accepted_enquiry($raw, $capture, true, static function (array $handle, array $receipt) use ($lock): array {
                if (!consent_valid_receipt_id($receipt['lead_id'] ?? null, 'BSRE-')
                    || !consent_valid_receipt_id($receipt['event_id'] ?? null, 'evt_')) throw new \RuntimeException('Invalid recovery receipt.');
                $row = $handle['row'];
                $repo = $handle['repository'];
                $repo->linkRecovery($row['request_id'], $row['fingerprint'], $receipt['lead_id'], $receipt['event_id'], $lock);
                return consent_denied_snapshot();
            }, $lock);
        });
    } catch (\Throwable $e) { return reply(503, 'ACCEPTANCE_UNCERTAIN_RETRY_SAME_ID', true); }
}

// The earlier forward build stored explicit refusals as route-bound intake-only captures.
// Match that retained evidence without recreating a capture or restoring a browser decision.
function offplan_country_retry_denied(string $raw, string $request_id, string $key): ?\WP_REST_Response {
    $store = consent_repository();
    $row = $store->findCapture(strtolower($request_id));
    if (!$row || $row['notice_version'] !== CONSENT_NOTICE_VERSION) return null;
    if (!hash_equals($row['fingerprint'], hash('sha256', $raw)) || !hash_equals($row['decision_version'], $key)
        || !in_array($row['state'], ['STAGED', 'ACCEPTED'], true)
        || $row['subject_key'] !== '' || (int) $row['original_revision'] !== 0
        || (int) $row['known'] !== 0 || (int) $row['eligible'] !== 0
        || (int) $row['analytics'] !== 0 || (int) $row['ad_measurement'] !== 0 || (int) $row['personalization'] !== 0
        || $row['click_capture_state'] !== 'NOT_PERMITTED') return reply(409, 'REQUEST_ID_CONFLICT');
    if ($row['state'] === 'ACCEPTED' && (int) $row['delivery_pending'] === 0) return offplan_country_recovery_receipt($row);
    return relay_accepted_enquiry($raw, ['recorded' => true, 'row' => $row, 'repository' => $store], true);
}

